   240                          /* literal header field without/never/with incremental indexing -- literal name */
   241                          if (*raw == 0x00)
   242                                  hpack_debug_printf("%02x: p17: literal without indexing : ", code);
   243                          else if (*raw == 0x10)
   244                                  hpack_debug_printf("%02x: p18: literal never indexed : ", code);
   245                          else if (*raw == 0x40)
   246                                  hpack_debug_printf("%02x: p16: literal with indexing : ", code);
   247
   248                          if (*raw == 0x40)
   249                                  must_index = 1;
   250
   251                          raw++; len--;
   252
   253                          /* retrieve name */
   254                          if (!len) { // truncated
   255                                  hpack_debug_printf("##ERR@%d##\n", __LINE__);
   256                                  ret = -HPACK_ERR_TRUNCATED;
   257                                  goto leave;
   258                          }
   259
   260                          huff = *raw & 0x80;
   261                          nlen = get_var_int(&raw, &len, 7);
   262                          if (len == (uint32_t)-1 || len < nlen) { // truncated
   263                                  hpack_debug_printf("##ERR@%d## (truncated): nlen=%d len=%d\n",
   264                                                     __LINE__, (int)nlen, (int)len);
   265                                  ret = -HPACK_ERR_TRUNCATED;
   266                                  goto leave;
   267                          }
   268
   269                          name = ist2(raw, nlen);
   270
   271                          raw += nlen;
   272                          len -= nlen;
   273
   274                          if (huff) {
   275                                  char *ntrash = chunk_newstr(tmp);
   276                                  if (!ntrash) {
   277                                          hpack_debug_printf("##ERR@%d##\n", __LINE__);
   278                                          ret = -HPACK_ERR_TOO_LARGE;
   279                                          goto leave;
   280                                  }
   281
   282                                  nlen = huff_dec((const uint8_t *)name.ptr, name.len, ntrash,
   283                                                  tmp->size - tmp->data);
   284                                  if (nlen == (uint32_t)-1) {
   285                                          hpack_debug_printf("2: can't decode huffman.\n");
   286                                          ret = -HPACK_ERR_HUFFMAN;
   287                                          goto leave;
   288                                  }
   289                                  hpack_debug_printf(" [name huff %d->%d] ", (int)name.len, (int)nlen);
   290
   291                                  tmp->data += nlen; // make room for the value
   292                                  name = ist2(ntrash, nlen);
   293                          }
   294
   295                          /* retrieve value */
   296                          if (!len) { // truncated
   297                                  hpack_debug_printf("##ERR@%d##\n", __LINE__);
   298                                  ret = -HPACK_ERR_TRUNCATED;
   299                                  goto leave;
   300                          }
   301
   302                          huff = *raw & 0x80;
   303                          vlen = get_var_int(&raw, &len, 7);
   304                          if (len == (uint32_t)-1 || len < vlen) { // truncated
   305                                  hpack_debug_printf("##ERR@%d## : vlen=%d len=%d\n",
   306                                                     __LINE__, (int)vlen, (int)len);
   307                                  ret = -HPACK_ERR_TRUNCATED;
   308                                  goto leave;
   309                          }
   310
   311                          value = ist2(raw, vlen);
   312                          raw += vlen;
   313                          len -= vlen;
   314
   315                          if (huff) {
   316                                  char *vtrash = chunk_newstr(tmp);
   317                                  if (!vtrash) {
   318                                          hpack_debug_printf("##ERR@%d##\n", __LINE__);
   319                                          ret = -HPACK_ERR_TOO_LARGE;
   320                                          goto leave;
   321                                  }
   322
   323                                  vlen = huff_dec((const uint8_t *)value.ptr, value.len, vtrash,
   324                                                  tmp->size - tmp->data);
   325                                  if (vlen == (uint32_t)-1) {
   326                                          hpack_debug_printf("3: can't decode huffman.\n");
   327                                          ret = -HPACK_ERR_HUFFMAN;
   328                                          goto leave;
   329                                  }
   330                                  hpack_debug_printf(" [value huff %d->%d] ", (int)value.len, (int)vlen);
